{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")
    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("invalid case field types")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError("required_symbols must contain strings")

    required = set(required_symbols)
    by_id = {}
    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        fields = ("id", "parent", "symbol", "depth", "removable", "utility")
        if any(field not in node for field in fields):
            raise ValueError("missing node field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node IDs must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("invalid parent")
        if not isinstance(symbol, str):
            raise ValueError("invalid symbol")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("invalid depth")
        if not isinstance(removable, bool):
            raise ValueError("invalid removable flag")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("invalid utility")
        by_id[node_id] = node

    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root = roots[0]
    if root["depth"] != 0:
        raise ValueError("root depth must be zero")

    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        parent = node["parent"]
        if parent is not None:
            if parent not in by_id:
                raise ValueError("parent must reference a node")
            children[parent].append(node["id"])
            if node["depth"] != by_id[parent]["depth"] + 1:
                raise ValueError("invalid tree depth")

    seen = set()
    stack = [root["id"]]
    while stack:
        node_id = stack.pop()
        if node_id in seen:
            raise ValueError("invalid tree structure")
        seen.add(node_id)
        stack.extend(children[node_id])
    if len(seen) != len(nodes):
        raise ValueError("tree must be connected and acyclic")

    active = set(by_id)
    removed = []
    while True:
        candidates = []
        for node_id in active:
            node = by_id[node_id]
            if node_id == root["id"] or not node["removable"]:
                continue
            if node["symbol"] in required:
                continue
            if any(child_id in active for child_id in children[node_id]):
                continue
            candidates.append(node)
        if not candidates:
            break
        candidate = min(candidates, key=lambda node: (-node["depth"], node["utility"], node["id"]))
        node_id = candidate["id"]
        active.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(active),
    }
"}
